insert into public.reg_pack (id, version, published_at, notes) values
  ('massachusetts-2026-09-03', 1, '2026-09-03T12:00:00Z', 'Massachusetts (DMF saltwater table, updated 2026-04-28): full finfish digest — striped bass slot 28" to <31" @1 with circle-hook/no-gaff/no-high-grading handling law, bluefish 5 (shore/private) vs 7 (for-hire), scup platform-split (shore 9.5", vessel/for-hire 11"), fluke vessel 17.5" vs shore 16.5" (May 24-Sep 23, 5/day), tautog four-season ladder (3/1/3/5, 16" min, one >21" trophy), black sea bass 16" (4 May 16-Aug 31, 2 Sep 1-Oct 14), cod WGOM 23" Sep 1-Oct 31 only & SNE prohibited, haddock GoM 17" 15/day Apr 1-Feb 28 (wraps) vs SNE 18" no limit, halibut 41" @1, winter flounder GoM 8 vs SNE 2, bonito/false albacore 16" curve-fork, combined-5; prohibited: ocean pout, river herring, windowpane, wolffish. Sharks doctrine quoted as note (54" min, 1/trip permitted list, circle hooks).')
on conflict (id) do nothing;

