  ('striped_bass', null, 'ma-statewide', 'salt', 'bag_limit', 'Striped Bass: 28" to less than 31". Open season: year round. Possession limit: 1 fish.', 'https://www.mass.gov/info-details/recreational-saltwater-fishing-regulations', 'Massachusetts DMF — Recreational saltwater fishing regulations', '2026-04-28', '2026-09-03', 1,
